دالة ثنائي(ع) {
    إذا (ع == ٠) { ارجع "٠" }
    متغير نص = ""
    من_أجل (ي من ١ إلى ع) {
        متغير باقي = ع % ٢
        نص = نص + نص(باقي)
        ع = ع / ٢
    }
    ارجع نص
}
